     1	import React, { useState } from 'react';
     2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     3	import { expect, within } from 'storybook/test';
     4	import { ZimmSubscribeModal } from './index';
     5	
     6	const meta: Meta<typeof ZimmSubscribeModal> = {
     7	  title: 'Forms/ZimmSubscribeModal',
     8	  component: ZimmSubscribeModal,
     9	};
    10	export default meta;
    11	type Story = StoryObj<typeof ZimmSubscribeModal>;
    12	
    13	/**
    14	 * Isolated mount — open by default so the panel renders without needing a trigger. Full dialog
    15	 * mechanics (focus entry, Tab trap, scroll lock, Escape) are mutation-tested at the footer
    16	 * assembly level (footer/index.stories.tsx's SubscribeModalOpen) and at the hook level
    17	 * (hooks/useZimmModal.test.tsx); testing.md says prove behaviour once, at the cheapest layer.
    18	 * This story is for components.md's per-exported-component requirement and the visual panel.
    19	 */
    20	export const Default: Story = {
    21	  render: () => {
    22	    const [isOpen, setIsOpen] = useState(true);
    23	    return (
    24	      <ZimmSubscribeModal
    25	        isOpen={isOpen}
    26	        onClose={() => setIsOpen(false)}
    27	        onSubmit={() => setIsOpen(false)}
    28	        privacyPolicyHref="/privacy-policy"
    29	      />
    30	    );
    31	  },
    32	  play: async () => {
    33	    // `find*`, not `get*`: useZimmModal starts `mounted: false` and ZimmModal returns null until
    34	    // it flips in an effect, so the portal contents do not exist on the first synchronous pass.
    35	    // `getByRole` threw before the effect had run. Queried through document.body rather than
    36	    // canvasElement because ZimmModal renders via createPortal — testing.md's canvasElement rule
    37	    // can't reach a portal root, which is why the scope was already widened here.
    38	    const doc = within(document.body);
    39	    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    40	    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    41	    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
    42	  },
    43	};

