=== useZimmModal.ts ===
     1	import { useCallback, useEffect, useRef, useState } from 'react';
     2	
     3	const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
     4	
     5	type UseZimmModalParams = {
     6	  /** Whether the dialog is currently open. */
     7	  isOpen: boolean;
     8	  /** Called when the dialog should close (Escape). */
     9	  onClose: () => void;
    10	};
    11	
    12	type UseZimmModalReturn = {
    13	  /** False until after the first client render, so the portal is not created during SSR. */
    14	  mounted: boolean;
    15	  /** Attach to the element that bounds the Tab trap — a <form> for SubscribeModal today, but any
    16	   *  container works. Everything focusable inside it is included in the trap. */
    17	  trapRef: React.RefObject<HTMLElement>;
    18	  /** Attach to the wrapper around the first field — its <input> receives initial focus. */
    19	  firstFocusRef: React.RefObject<HTMLDivElement>;
    20	};
    21	
    22	/**
    23	 * Generic dialog mechanics: mount gating, focus save/restore, body-scroll lock, and the
    24	 * Escape/Tab keyboard trap. Renamed from useSubscribeModal — the logic never depended on
    25	 * anything subscribe-specific, only on a trap boundary and a first-focus target, so any modal
    26	 * built on the ZimmModal atom can reuse it.
    27	 *
    28	 * Extracted from SubscribeModal per components.md's extract-to-hook threshold — four effects,
    29	 * three of them with cleanup functions. None of it touches JSX, so the component keeps only its
    30	 * markup and the recipe lookup. Behaviour is unchanged from useSubscribeModal; the effect order
    31	 * and dependency arrays are preserved exactly, because focus restore depends on running after
    32	 * the open-effect's cleanup.
    33	 *
    34	 * @param params isOpen and the close callback
    35	 * @returns the mount flag plus the two refs the dialog markup has to attach
    36	 */
    37	export const useZimmModal = ({ isOpen, onClose }: UseZimmModalParams): UseZimmModalReturn => {
    38	  const [mounted, setMounted] = useState(false);
    39	  const trapRef = useRef<HTMLElement>(null);
    40	  const firstFocusRef = useRef<HTMLDivElement>(null);
    41	  const triggerRef = useRef<Element | null>(null);
    42	
    43	  useEffect(() => {
    44	    setMounted(true);
    45	  }, []);
    46	
    47	  // Save the trigger element on open so focus can be restored on close
    48	  useEffect(() => {
    49	    if (isOpen) {
    50	      triggerRef.current = document.activeElement;
    51	      // Defer so the portal has rendered before we try to focus inside it
    52	      const id = setTimeout(() => {
    53	        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
    54	        firstInput?.focus();
    55	      }, 0);
    56	      return () => clearTimeout(id);
    57	    } else {
    58	      // Return focus to the element that opened the modal
    59	      if (triggerRef.current instanceof HTMLElement) {
    60	        triggerRef.current.focus();
    61	      }
    62	    }
    63	  }, [isOpen]);
    64	
    65	  // Lock body scroll while modal is open
    66	  useEffect(() => {
    67	    if (!isOpen) return;
    68	    const prev = document.body.style.overflow;
    69	    document.body.style.overflow = 'hidden';
    70	    return () => {
    71	      document.body.style.overflow = prev;
    72	    };
    73	  }, [isOpen]);
    74	
    75	  // Keyboard: Escape to close, Tab trap within the modal
    76	  const handleKeyDown = useCallback(
    77	    (e: KeyboardEvent) => {
    78	      if (e.key === 'Escape') {
    79	        onClose();
    80	        return;
    81	      }
    82	      if (e.key !== 'Tab' || !trapRef.current) return;
    83	
    84	      const focusable = Array.from(trapRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    85	        (el) => !el.hasAttribute('disabled'),
    86	      );
    87	      if (focusable.length === 0) {
    88	        e.preventDefault();
    89	        return;
    90	      }
    91	
    92	      const first = focusable[0];
    93	      const last = focusable[focusable.length - 1];
    94	      const active = document.activeElement;
    95	
    96	      // Focus can end up outside the trap boundary entirely — e.g. a click on the backdrop
    97	      // before it closes. The two boundary checks below only redirect Tab *at* an edge; without
    98	      // this branch, Tab from an already-escaped focus point would carry the user out into the
    99	      // page behind the modal (WCAG 2.1.2 — no trap the keyboard cannot get back into).
   100	      if (!(active instanceof Node) || !trapRef.current.contains(active)) {
   101	        e.preventDefault();
   102	        (e.shiftKey ? last : first).focus();
   103	      } else if (e.shiftKey && active === first) {
   104	        e.preventDefault();
   105	        last.focus();
   106	      } else if (!e.shiftKey && active === last) {
   107	        e.preventDefault();
   108	        first.focus();
   109	      }
   110	    },
   111	    [onClose],
   112	  );
   113	
   114	  useEffect(() => {
   115	    if (!isOpen) return;
   116	    document.addEventListener('keydown', handleKeyDown);
   117	    return () => document.removeEventListener('keydown', handleKeyDown);
   118	  }, [isOpen, handleKeyDown]);
   119	
   120	  return { mounted, trapRef, firstFocusRef };
   121	};

