const lum=h=>{const n=h.replace("#","");const p=n.length===3?[0,1,2].map(i=>parseInt(n[i]+n[i],16)/255):[0,2,4].map(i=>parseInt(n.substr(i,2),16)/255);
const ch=p.map(c=>c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4));return 0.2126*ch[0]+0.7152*ch[1]+0.0722*ch[2];};
const r=(a,b)=>{const x=lum(a),y=lum(b);const[h,l]=x>y?[x,y]:[y,x];return (h+0.05)/(l+0.05);};
const f=n=>Math.floor(n*100)/100;
console.log("heading #969696 on decorator #191919 :", f(r("#969696","#191919")), "-> PASS (>=4.5)");
console.log("heading #969696 on SB canvas  #333   :", f(r("#969696","#333")),    "-> FAIL (<4.5)");
console.log("heading #969696 on plain white       :", f(r("#969696","#ffffff")), "-> FAIL (<4.5)");
'
echo ""
echo "=== does the a11y check still pass on the rebuilt story? ==="
npx test-storybook --url http://127.0.0.1:7413 --ci --verbose zimmSubscribe > "$D/tsb-v2.log" 2>&1; echo "EXIT=$?"
LC_ALL=C perl -pe 's/\e\[[0-9;]*m//g' "$D/tsb-v2.log" | grep -E "✓|✕|Tests:|contrast of"

