cat > "$D/probe4.mjs" <<'EOF'
import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 900, height: 600 } });
await p.goto('http://127.0.0.1:7413/iframe.html?id=forms-zimmsubscribesection--default&viewMode=story', { waitUntil: 'load' });
await p.waitForSelector('#storybook-root > div', { timeout: 10000 });
await p.waitForTimeout(400);
// Reproduce EXACTLY what SB10's backgrounds decorator injects, but with a CSS var as the value.
const r = await p.evaluate(() => {
  const before = getComputedStyle(document.querySelector('.sb-show-main')).backgroundColor;
  const s = document.createElement('style');
  s.textContent = '.sb-show-main { background: var(--zimm-color-bg-05) !important; }';
  document.head.appendChild(s);
  const after = getComputedStyle(document.querySelector('.sb-show-main')).backgroundColor;
  const deco  = getComputedStyle(document.querySelector('#storybook-root > div')).backgroundColor;
  return { canvas_before: before, canvas_after_varInjection: after, decorator: deco,
           match: after === deco };
});
console.log(JSON.stringify(r, null, 2));
await p.screenshot({ path: process.env.OUT + '/shot-v2-varcanvas.png' });
await b.close();
EOF
OUT="$D" node "$D/probe4.mjs" 2>&1 | tail -12

